package com.cekalix.controlador;
import com.cekalix.util.ConexionBD;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;import java.util.*;
@WebServlet("/reportes")
public class ReporteServlet extends HttpServlet {protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{String sql="SELECT COUNT(*) cantidad,COALESCE(SUM(total),0) total FROM venta WHERE estado='EMITIDA'";try(Connection c=ConexionBD.obtenerConexion();PreparedStatement s=c.prepareStatement(sql);ResultSet r=s.executeQuery()){r.next();q.setAttribute("cantidadVentas",r.getInt("cantidad"));q.setAttribute("totalVentas",r.getBigDecimal("total"));List<Map<String,Object>> rows=new ArrayList<>();try(PreparedStatement x=c.prepareStatement("SELECT DATE(fecha) dia,SUM(total) total,COUNT(*) cantidad FROM venta WHERE fecha>=CURRENT_DATE-INTERVAL 30 DAY GROUP BY DATE(fecha) ORDER BY dia DESC");ResultSet z=x.executeQuery()){while(z.next()){Map<String,Object> m=new HashMap<>();m.put("dia",z.getDate("dia"));m.put("total",z.getBigDecimal("total"));m.put("cantidad",z.getInt("cantidad"));rows.add(m);}}q.setAttribute("resumen",rows);}catch(SQLException e){throw new ServletException(e);}q.getRequestDispatcher("/WEB-INF/vistas/reportes.jsp").forward(q,p);}}